WITH lines AS (SELECT id, service, level, attr_key, v FROM app_logs LATERAL VIEW EXPLODE(context) x AS attr_key, v), valid AS (SELECT *, INITCAP(TRIM(attr_key)) AS attr_key_title, SUBSTRING(service, 1, 3) AS service_prefix FROM lines WHERE attr_key IS NULL), valid_app_logs AS (SELECT *, CONCAT(attr_key, '/', level) AS attr_key_level, INITCAP(TRIM(service)) AS service_title, COALESCE(attr_key, 'UNKNOWN') AS attr_key_filled FROM valid WHERE service IN ('billing', 'checkout', 'search')), valid_app_logs_2 AS (SELECT id, service, attr_key, v, attr_key_title, attr_key_level, service_title, attr_key_filled, LOWER(attr_key) AS attr_key_lower, COALESCE(attr_key, 'UNKNOWN') AS resolved_attr_key FROM valid_app_logs WHERE attr_key IS NOT NULL), cleaned AS (SELECT id, service, attr_key, attr_key_title, attr_key_level, resolved_attr_key, CASE WHEN service IN ('checkout', 'auth') THEN 'Priority' ELSE 'Other' END AS service_group FROM valid_app_logs_2 WHERE attr_key IS NOT NULL), matched_keys AS (SELECT service, id FROM cleaned INTERSECT SELECT service, id FROM app_logs WHERE HOUR(log_ts) BETWEEN 10 AND 17), verified AS (SELECT s.* FROM cleaned s INNER JOIN matched_keys k ON s.service = k.service AND s.id = k.id) SELECT attr_key, SIZE(COLLECT_SET(attr_key)) AS num_attr_keys, COUNT(DISTINCT attr_key) AS distinct_attr_keys, COUNT(*) AS num_rows, SIZE(COLLECT_SET(service)) AS num_services, COUNT(DISTINCT service) AS distinct_services, SIZE(COLLECT_SET(service)) AS num_services_2 FROM verified GROUP BY 1 HAVING distinct_attr_keys >= 1 ORDER BY num_attr_keys
